// GetRoleWithResponse Answer which role a principal holds on a scope now.
//
// The role question (ADR 0056), which the shared service library asks with a deadline of 250 ms and no retry. Made for a caller, the call carries the caller's internal token, and the question is about the token's principal, so `principal` is absent. Made with no user, it carries a workload token whose `operations` include `getRole`, and `principal` names the principal (ADR 0040). The role that counts is the highest that the member holds on the scope or on a scope that contains it. `none` is an answer and not an error: a principal who is no member of the scope's organization, a removed member and a scope that was never registered all get it. One call answers for one scope.
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /internal/v1/role (the `GetRole` operationId).
func (c *ClientWithResponses) GetRoleWithResponse(ctx context.Context, params *GetRoleParams, reqEditors ...RequestEditorFn) (*GetRoleResponse, error) {
	rsp, err := c.GetRole(ctx, params, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseGetRoleResponse(rsp)
}

// ListScopesWithResponse List the scopes on which the caller holds a role.
//
// The scopes question. The call carries the caller's internal token, and lists every scope on which the token's principal holds a role itself, in every organization of which they are an active member, each with that role and the scopes that contain it. A role on an organization stands for all its projects and sites, so the list is short. The shared service library caches it by the rules of the role answer.
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /internal/v1/scopes (the `ListScopes` operationId).
func (c *ClientWithResponses) ListScopesWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ListScopesResponse, error) {
	rsp, err := c.ListScopes(ctx, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseListScopesResponse(rsp)
}

